mapper.sql:
FROM merchant m
INNER JOIN operators o ON m.id = o.merchant_id

	m.company_id = #{companyId}
	AND o.operator_type = 'merchant'

		AND o.merchant_id = #{merchantId}


		AND o.is_merchant_main = 1


		AND o.mobile = #{mobileEnc}


		AND m.merchant_name LIKE CONCAT('%', #{merchantNameLike}, '%')
